type Campaign = { id: string; name: string; message: string; mediaType?: "image" | "video" | null; mediaUrl?: string | null; mediaMimeType?: string | null; mediaFileName?: string | null; status: "Draft" | "Queued" | "Sending" | "Paused" | "Completed" | "Cancelled" | "Failed"; audience: number; sent: number; failed: number; created: string; createdAt: string };
